def page(name, *ps):
    return {"name": name, "html": "".join(p if p.startswith("<") else f"<p>{p}</p>" for p in ps)}

def ul(*items):
    return "<ul>" + "".join(f"<li>{i}</li>" for i in items) + "</ul>"

