# Новые архетипы (Players Guide, гл. 1) — для всех типов
ARCHETYPES = [
    {"name": "Верящий", "regain": "убедить неверящего, что у случившегося сверхъестественное объяснение."},
    {"name": "Переговорщик", "regain": "добиться важной цели уговором, без силы и обмана."},
    {"name": "Скептик", "regain": "убедить человека в разумном, научном объяснении того, что казалось ему сверхъестественным."},
]


def build():
    edges = []
    for path, lvl, name, attr, diff, cost, passive, text in EDGES:
        key = f"{path}|{lvl}"
        edges.append({"key": key, "path": path, "virtue": PATH_VIRTUE[path], "level": lvl, "name": name,
                      "roll": None if passive else {"trait1": attr or "", "trait2": ROLL_ABILITY.get(key, f"hunter.{PATH_VIRTUE[path]}"),
                                                    "difficulty": diff or 6, "byTarget": diff is None},
                      "conviction": cost, "text": text})
    for b in BACKGROUNDS:
        b.update({"line": "hunter", "source": "Hunter: The Reckoning", "min": 1, "max": 5})
        if b["en"] in ("Destiny", "Patron"):    # Свидетелям недоступны (Players Guide, гл. 1)
            b["noBystander"] = True
    data = {"source": "Hunter: The Reckoning", "virtues": VIRTUES, "creeds": CREEDS, "edges": edges,
            "backgrounds": BACKGROUNDS, "bystander": BYSTANDER, "archetypes": ARCHETYPES, "rules": RULES}
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
    return {"creeds": len(CREEDS), "edges": len(edges), "backgrounds": len(BACKGROUNDS)}


if __name__ == "__main__":
    print(build())
